// Regression tests for the scientific-correctness bugs found when comparing CROW
// against bioRad 0.12.0 and vol2bird. Each test names the bug it guards.
//
// Reference data: Wideumont (bewid) 12-14 October 2020 from the meteo.be open
// data server, and bioRad outputs generated by data/generate_biorad_references.R
import helpers from "@/helpers";
import config from "@/config";
import { VPTSDataRowFromFile } from "@/CrowTypes";
import VPChart from "@/components/VPChart.vue";
import VPIChart from "@/components/VPIChart.vue";
import moment from "moment-timezone";
import { UserChoicesStoreModule } from "@/store/UserChoicesStore";
import { mockMeteoBe, mountChart, mountHome, readBewid, readBioradCsv, restoreMocks, settle } from "./support";

describe("A1 - vol2bird fixed-width parser", () => {
  test("every numeric field matches the whitespace-separated vol2bird columns", () => {
    /*
    vol2bird writes eta as a 6-wide field (columns 69-74). The parser used to
    read one character too late, so eta >= 1000 (exactly at peak migration)
    lost its leading digit: 1081.2 was read as 81.2, halving VIR and RTR.
    This checks every row of three real days against an independent
    whitespace split of the same line (bioRad's own parsing strategy).
    */
    config.appTemporalResolution = 5 * 60; // no flooring, 1:1 with the file

    for (const content of readBewid()) {
      const dataLines = content.split("\n").slice(4, -1);
      const parsed = helpers.parseVpts(content, "VOL2BIRD");
      expect(parsed.length).toBe(dataLines.length);

      parsed.forEach((row, i) => {
        const cols = dataLines[i].trim().split(/\s+/);
        expect(row.height).toBe(parseInt(cols[2]));
        expect(row.ff).toEqual(parseFloat(cols[6]));
        expect(row.dd).toEqual(parseFloat(cols[7]));
        expect(row.sd_vvp).toEqual(parseFloat(cols[8]));
        expect(row.eta).toEqual(parseFloat(cols[11]));
        expect(row.dens).toEqual(parseFloat(cols[12]));
      });
    }
  });

  test("a real peak-migration row keeps its eta above 1000", () => {
    /*
    Concrete instance of the bug above, taken from bewid 2020-10-12 19:00 at
    1200 m, so a failure points straight at the eta column.
    */
    const header = "#\n#\n#\n#\n";
    const row = "20201012 1900 1200  -6.63  -8.66   -0.85 10.91 217.5   2.39 F   4.61 1081.2  98.29   4.39  9413 13368 11863 17193\n";
    const [parsed] = helpers.parseVpts(header + row + "\n", "VOL2BIRD");
    expect(parsed.eta).toBe(1081.2);
    expect(parsed.dens).toBe(98.29);
  });

  test("the last data row is kept when the file lacks a final newline", () => {
    /*
    The parser always discarded the last line, assuming it was blank. The
    hand-truncated BEHEL fixture ends without a newline, so its 11:30 / 4800 m
    layer (eta 0.2) was lost and VIR differed from bioRad by 0.04.
    */
    const header = "#\n#\n#\n#\n";
    const row = "20201012 1900 1200  -6.63  -8.66   -0.85 10.91 217.5   2.39 F   4.61 1081.2  98.29   4.39  9413 13368 11863 17193";
    expect(helpers.parseVpts(header + row, "VOL2BIRD").length).toBe(1);
    expect(helpers.parseVpts(header + row + "\n", "VOL2BIRD").length).toBe(1);
  });
});

describe("A2 - total number of birds (cumulative migration traffic)", () => {
  // Build the VPI entries exactly as the app does for a given UTC window:
  // parse at app resolution, keep the first record per height in each slot,
  // drop non-bird rows (filterVpts), then integrate each slot.
  function appMtrSeries(contents: string[], fromIso: string, toIso: string): number[] {
    config.appTemporalResolution = 10 * 60;
    const heights = config.availableRadars[0].options[0].heights.length;
    const rows = contents.flatMap(c =>
      helpers.filterVpts(
        Object.values(helpers.groupBy(helpers.parseVpts(c, "VOL2BIRD"), x => x.datetime))
          .map(g => g.slice(0, heights))
          .flat()
      )
    );
    const bySlot = helpers.groupBy(rows, r => r.datetime);
    const series = [];
    for (let t = Date.parse(fromIso); t < Date.parse(toIso); t += 10 * 60 * 1000) {
      series.push(bySlot[t] ? helpers.integrateProfile(bySlot[t]).mtr : NaN);
    }
    return series;
  }

  test("matches bioRad's cumulative traffic (mt) for 12 Oct 2020 within 1%", () => {
    /*
    The "about N birds flew across a 1 km line" sentence used to average the
    non-NaN MTRs and multiply by the window length. Profiles where no layer
    passes the sd_vvp filter (no birds) were treated as missing and imputed
    with the mean of the others: 33,000 birds on 12 Oct against bioRad's
    22,537. bioRad counts them as 0 and integrates MTR over time.
    */
    const reference = readBioradCsv("bewid_20201012-14.biorad_vpi_5min.csv");
    const bioradMt = +reference.filter((r: string[]) => r[0] < "2020-10-13")
      .slice(-1)[0][5];

    const mtr = appMtrSeries(readBewid().slice(0, 1), "2020-10-12T00:00:00Z", "2020-10-13T00:00:00Z");
    const total = helpers.totalNumberOfBirds(mtr, 10 * 60);

    expect(Math.abs(total - bioradMt) / bioradMt).toBeLessThan(0.01);
  });

  test("no-bird profiles count as zero, not as missing", () => {
    /*
    Half of a 24 h window at MTR 1000 birds/km/h and half without birds must
    give 12,000 birds; imputing the empty half with the mean gave 24,000.
    */
    const mtr = [...Array(72).fill(1000), ...Array(72).fill(NaN)];
    expect(helpers.totalNumberOfBirds(mtr, 10 * 60)).toBe(12000);
  });

  test("a window without any bird profile gives 0, not NaN", () => {
    /*
    Averaging an empty array made the sentence read "about NaN birds".
    */
    expect(helpers.totalNumberOfBirds([NaN, NaN], 10 * 60)).toBe(0);
    expect(helpers.totalNumberOfBirds([], 10 * 60)).toBe(0);
  });

  test("the result is rounded to the nearest hundred", () => {
    /*
    The sentence says "about", so the precision shown must not suggest more
    accuracy than the method has; this keeps the existing rounding.
    */
    expect(helpers.totalNumberOfBirds([1234 * 6], 10 * 60)).toBe(1200);
    expect(helpers.totalNumberOfBirds([1250 * 6], 10 * 60)).toBe(1300);
  });
});

describe("A3 - the time window does not shrink on reload", () => {
  beforeEach(() => { config.appTemporalResolution = 10 * 60; });
  afterEach(restoreMocks);

  test("the bioRad-comparison URL shows the full 72 h", async () => {
    /*
    getDatesForData() called .subtract() on the endMoment owned by the store,
    removing 10 min from the window each time data was (re)loaded. Opening
    ?radar=bewid&date=2020-10-13&interval=72&timedisplay=UTC triggers several
    loads and showed 429 slots ending 23:20 instead of 432 ending 23:50.
    */
    mockMeteoBe();
    const wrapper = mountHome({ radar: "bewid", date: "2020-10-13", interval: 72, timeDisplay: "UTC" });
    await settle();
    const slots = Object.keys((wrapper.vm as any).radarVpts).map(Number).sort();
    expect(slots.length).toBe(432);
    expect(new Date(slots[0]).toISOString()).toBe("2020-10-12T00:00:00.000Z");
    expect(new Date(slots[431]).toISOString()).toBe("2020-10-14T23:50:00.000Z");
  });

  test("switching radar repeatedly keeps a 24 h window", async () => {
    /*
    In UTC mode the window does not depend on the radar, so each radar switch
    used to remove another 10 min from the same cached moment.
    */
    mockMeteoBe();
    const wrapper = mountHome({ radar: "bewid", date: "2020-10-13", interval: 24, timeDisplay: "UTC" });
    await settle();
    for (const radar of ["bejab", "bewid", "bejab"]) {
      UserChoicesStoreModule.setSelectedRadarCode(radar);
      await settle();
      expect(Object.keys((wrapper.vm as any).radarVpts).length).toBe(144);
    }
  });
});

describe("A4 - responses for a previous selection are discarded", () => {
  beforeEach(() => { config.appTemporalResolution = 10 * 60; });
  afterEach(restoreMocks);

  test("a slow response for the previous radar does not overwrite the current one", async () => {
    /*
    storeDataRow() only checked that the timestamp slot existed, so a response
    for radar A arriving after the user switched to radar B was written into
    B's grid, mixing two radars on screen. Radar A's (behel) file here holds
    the 12 Oct values relabelled as 13 Oct, so any leak is detectable.
    */
    let releaseBehel: () => void = () => undefined;
    const behelData = readBewid()[0].replace(/^20201012 /gm, "20201013 ");
    mockMeteoBe(url => url.includes("/behel/")
      ? new Promise(resolve => { releaseBehel = () => resolve({ data: behelData }); })
      : undefined);

    const wrapper = mountHome({ radar: "behel", date: "2020-10-13", interval: 24, timeDisplay: "UTC" });
    await settle();
    UserChoicesStoreModule.setSelectedRadarCode("bewid");
    await settle();
    releaseBehel();
    await settle();

    // bewid's own values as the app keeps them: first record per 10 min slot and
    // height, then the sd_vvp filter
    const firstPerSlot = new Map<string, VPTSDataRowFromFile>();
    for (const row of helpers.parseVpts(readBewid()[1], "VOL2BIRD")) {
      const key = `${row.datetime}/${row.height}`;
      if (!firstPerSlot.has(key)) firstPerSlot.set(key, row);
    }
    const expected = new Map<string, number>();
    helpers.filterVpts(Array.from(firstPerSlot.values())).forEach(r => expected.set(`${r.datetime}/${r.height}`, r.dens));
    const grid = (wrapper.vm as any).radarVpts;
    let checked = 0;
    expected.forEach((dens, key) => {
      const [datetime, height] = key.split("/");
      if (grid[datetime]) {
        expect(grid[datetime].heightData[height].dens).toBe(dens);
        checked++;
      }
    });
    expect(checked).toBeGreaterThan(500); // sanity floor: 830 cells pass the sd_vvp filter on 13 Oct
  });
});

describe("A5 - BirdTAM codes saturate at 9", () => {
  test("very high densities map to BirdTAM 9 instead of wrapping around", () => {
    /*
    densityToBirdtam() had no upper bound, and the ordinal colour scale recycles
    its range for unknown codes: 320 birds/km3 (code 10) was drawn white like
    BirdTAM 0, 700 light green. Code 9 is the top class (extremes and rain).
    */
    expect(helpers.densityToBirdtam(150)).toBe(8);
    expect(helpers.densityToBirdtam(200)).toBe(9);
    expect(helpers.densityToBirdtam(320)).toBe(9);
    expect(helpers.densityToBirdtam(1e6)).toBe(9);
    expect(config.VPChartStyle.birdtamColors.get(helpers.densityToBirdtam(1000))).toBe("#333333");
  });
});

describe("A7 - feet axis lines up with the metre axis", () => {
  test("a height in feet sits at the same pixel as the same height in metres", () => {
    /*
    The metre axis spans 0 to 5000 m (top of the 4800 m layer) but the feet
    axis was scaled to 3.2808 x 4800 ft over the same pixels, so the feet
    labels drifted by up to ~650 ft (about 4%) at the top of the chart.
    */
    const heights = Array.from({ length: 25 }, (_, i) => i * 200);
    const vptsData = [0, 10].flatMap(minutes => heights.map(height => ({
      timestamp: Date.parse("2020-10-13T00:00:00Z") + minutes * 60 * 1000, height, dd: 0, ff: 0, dens: 1, sd_vvp: 3, noData: false
    })));
    const wrapper = mountChart(VPChart, { vptsData, styleConfig: config.VPChartStyle, scheme: "viridis", showTimeAs: "UTC" });
    const vm = wrapper.vm as any;
    for (const meters of [0, 1000, 3000, 5000]) {
      expect(vm.yScaleFeet(meters * 3.2808)).toBeCloseTo(vm.yScale(String(meters)), 6);
    }
  });
});

describe("A10 - VPI tooltip picks the nearest profile", () => {
  test("the mouse closer to the next slot selects the next slot", () => {
    /*
    mouseMove() compared seconds (x0.getTime() / 1000) with milliseconds, so the
    comparison was always false and the tooltip always showed the previous
    slot, up to 10 min early.
    */
    const start = moment.utc("2020-10-13T00:00:00Z");
    const vpiData = [0, 1, 2].map(i => ({
      moment: start.clone().add(i * 10, "minutes"),
      integratedProfiles: { mtr: 100 * (i + 1), rtr: 0, vid: 0, vir: 0 }
    }));
    const wrapper = mountChart(VPIChart, { vpiData, styleConfig: config.VPIChartStyle, showTimeAs: "UTC", appTemporalResolution: 600, mode: "mtr", loading: false });
    const vm = wrapper.vm as any;
    const hover = (minutes: number) => vm.mouseMove({
      clientX: vm.xScale(start.clone().add(minutes, "minutes").toDate()),
      target: { getBoundingClientRect: () => ({ left: 0 }) }
    });

    hover(8); // 2 min before the 00:10 slot
    expect(vm.VPIEntryAtTimeX).toBe(vpiData[1]);
    hover(12); // 2 min after it
    expect(vm.VPIEntryAtTimeX).toBe(vpiData[1]);
    hover(2);
    expect(vm.VPIEntryAtTimeX).toBe(vpiData[0]);
  });
});

describe("A9 - integrateProfile with a migration direction (alpha)", () => {
  // One 200 m layer flying at 10 m/s with 100 birds/km3, heading `dd` degrees
  const layer = (dd: number) => [{ datetime: 0, height: 0, dd, ff: 10, dens: 100, sd_vvp: 3, eta: 0 }];

  test("a numeric alpha is accepted", () => {
    /*
    The argument check was inverted: any numeric alpha threw "'alpha' needs to
    be numeric or NaN", so the directional MTR could never be computed.
    */
    expect(() => helpers.integrateProfile(layer(90), 0, Infinity, 200, 2, 90)).not.toThrow();
  });

  test("MTR is projected on alpha with the angle in degrees", () => {
    /*
    The code computed cos(dd - alpha) * PI / 180 (cosine of degrees taken as
    radians, then scaled) instead of cos((dd - alpha) * PI / 180), as bioRad's
    integrate_profile does. Flying along alpha keeps the full MTR (720),
    against it gives -720, perpendicular to it gives 0.
    */
    expect(helpers.integrateProfile(layer(90), 0, Infinity, 200, 2, 90).mtr).toBeCloseTo(720, 6);
    expect(helpers.integrateProfile(layer(180), 0, Infinity, 200, 2, 0).mtr).toBeCloseTo(-720, 6);
    expect(helpers.integrateProfile(layer(90), 0, Infinity, 200, 2, 0).mtr).toBeCloseTo(0, 6);
  });

  test("without alpha, MTR is non-directional (the app's default)", () => {
    /*
    The UI never passes alpha: MTR must stay the plain ff x dens sum, as with
    bioRad's default alpha = NA.
    */
    expect(helpers.integrateProfile(layer(180)).mtr).toBeCloseTo(720, 6);
  });
});

describe("B2 - layers with an undefined sd_vvp are kept, as in bioRad", () => {
  const row = (sd_vvp: number) => ({ datetime: 0, height: 0, dd: NaN, ff: NaN, dens: 0.5, sd_vvp, eta: 5.5 });

  test("only a measured sd_vvp below the threshold removes a layer", () => {
    /*
    vol2bird writes a density even where it cannot estimate sd_vvp (NaN), and
    bioRad keeps it: `x[sd_vvp < threshold] <- 0` does not select NA. CROW used
    to drop those rows, lowering VID by ~2.7% over the Wideumont sample and
    drawing those (mostly high-altitude) cells as "no data".
    */
    expect(helpers.filterVpts([row(NaN), row(1.9), row(2), row(3)]).map(r => r.sd_vvp))
      .toEqual([NaN, 2, 3]);
    expect(helpers.integrateProfile([row(NaN)]).vid).toBeCloseTo(0.1, 6);
    expect(helpers.integrateProfile([row(1.9)]).vid).toBeNaN();
    expect(helpers.integrateProfile([]).vid).toBeNaN(); // a slot with nothing loaded
  });

  test("a layer without any measurement stays 'no data'", () => {
    /*
    Keeping NaN-sd_vvp layers must not turn layers where vol2bird measured
    nothing (dens and eta both nan) into a measured density of 0: those were
    drawn as "0 birds/km3" instead of grey no-data cells (2,529 layers over the
    three Wideumont days). bioRad shows them as NA too. A remaining NaN in a
    kept layer counts as 0, so colours and integrals stay defined.
    */
    const empty = { datetime: 0, height: 0, dd: NaN, ff: NaN, dens: NaN, sd_vvp: NaN, eta: NaN };
    expect(helpers.filterVpts([empty])).toEqual([]);
    expect(helpers.filterVpts([{ ...empty, eta: 0.2 }])).toEqual([{ ...empty, eta: 0.2, dens: 0 }]);
    expect(helpers.filterVpts([{ ...empty, sd_vvp: 3, eta: 4 }])).toEqual([{ ...empty, sd_vvp: 3, eta: 4, dens: 0 }]);
    // sd_vvp measured but no density (review item B3, unchanged): kept, as 0
    expect(helpers.filterVpts([{ ...empty, sd_vvp: 3 }])).toEqual([{ ...empty, sd_vvp: 3, dens: 0, eta: 0 }]);
  });

  test("every 5 min Wideumont profile matches bioRad's MTR, VID, VIR and RTR", () => {
    /*
    End-to-end check of parsing (A1), sd_vvp filtering (B2) and integration
    against bioRad 0.12.0 on 843 real profiles. A profile where no layer passes
    the filter is NaN in CROW (shown as a gap) and 0 in bioRad; that display
    choice is separate (B1), so NaN is compared as 0 here.
    */
    config.appTemporalResolution = 5 * 60;
    const reference = readBioradCsv("bewid_20201012-14.biorad_vpi_5min.csv");
    const bySlot = helpers.groupBy(
      readBewid().flatMap(c => helpers.filterVpts(helpers.parseVpts(c, "VOL2BIRD"))), r => r.datetime);
    const round3 = (x: number) => Math.round(((Number.isNaN(x) ? 0 : x) + Number.EPSILON) * 1000) / 1000;

    expect(reference.length).toBe(843);
    for (const [datetime, mtr, rtr, vid, vir] of reference) {
      const rows = bySlot[Date.parse(datetime)] || [];
      const crow = rows.length ? helpers.integrateProfile(rows) : { mtr: NaN, rtr: NaN, vid: NaN, vir: NaN };
      expect([datetime, round3(crow.mtr), round3(crow.vid), round3(crow.vir), round3(crow.rtr)])
        .toEqual([datetime, round3(+mtr), round3(+vid), round3(+vir), round3(+rtr)]);
    }
  });
});
